import { requireAuth, getServiceClient, errorResponse } from './_lib.js';
import { Resend } from 'resend';
import { jsPDF } from 'jspdf';

const resend = new Resend(process.env.RESEND_API_KEY);

const COMPANY_LOGO_B64 = 'data:image/jpeg;base64,';

const drawTable = (doc, items, startY) => {
  let y = startY;
  const pageHeight = doc.internal.pageSize.height;
  const pageWidth = doc.internal.pageSize.width;
  const margin = 14;
  const tableWidth = pageWidth - margin * 2;
  const colWidths = [tableWidth * 0.55, tableWidth * 0.15, tableWidth * 0.15, tableWidth * 0.15];

  const drawHeader = () => {
    doc.setFillColor(41, 128, 185);
    doc.rect(margin, y, tableWidth, 9, 'F');
    doc.setTextColor(255);
    doc.setFont(undefined, 'bold');
    doc.setFontSize(10);
    let x = margin + 2;
    doc.text('Part Description', x, y + 6);
    x += colWidths[0]; doc.text('Qty', x - 2, y + 6, { align: 'right' });
    x += colWidths[1]; doc.text('Unit Cost', x - 2, y + 6, { align: 'right' });
    x += colWidths[2]; doc.text('Total Cost', x - 2, y + 6, { align: 'right' });
    y += 9;
  };

  drawHeader();
  doc.setTextColor(0);
  doc.setFont(undefined, 'normal');
  doc.setFontSize(9);

  (items || []).forEach((item, index) => {
    const descLines = doc.splitTextToSize(item.description || '', colWidths[0] - 4);
    const rowH = Math.max(8, descLines.length * 4) + 2;
    if (y + rowH > pageHeight - 30) { doc.addPage(); y = 20; drawHeader(); }
    if (index % 2 !== 0) { doc.setFillColor(245, 245, 245); doc.rect(margin, y, tableWidth, rowH, 'F'); }
    let x = margin + 2;
    doc.text(descLines, x, y + 5);
    x += colWidths[0]; doc.text(String(item.quantity_ordered || 0), x - 2, y + rowH / 2, { align: 'right', baseline: 'middle' });
    x += colWidths[1]; doc.text(`$${(item.unit_cost || 0).toFixed(2)}`, x - 2, y + rowH / 2, { align: 'right', baseline: 'middle' });
    x += colWidths[2]; doc.text(`$${(item.total_cost || 0).toFixed(2)}`, x - 2, y + rowH / 2, { align: 'right', baseline: 'middle' });
    y += rowH;
  });
  return y;
};

export default async function handler(req, res) {
  if (req.method !== 'POST') return errorResponse(res, 405, 'Method not allowed');

  try {
    const admin = await requireAuth(req);
    if (admin.role !== 'admin' && admin.role !== 'technician') {
      return errorResponse(res, 403, 'Insufficient permissions');
    }

    const { purchaseOrderId, message } = req.body;
    if (!purchaseOrderId) return errorResponse(res, 400, 'purchaseOrderId required');

    const db = getServiceClient();

    const { data: po, error: poError } = await db.from('purchase_orders').select('*').eq('id', purchaseOrderId).maybeSingle();
    if (poError) { console.error('PO fetch error:', poError.message); return errorResponse(res, 500, 'Database error: ' + poError.message); }
    if (!po) return errorResponse(res, 404, `Purchase order ${purchaseOrderId} not found`);

    const { data: supplier, error: supplierError } = await db.from('suppliers').select('*').eq('id', po.supplier_id).maybeSingle();
    if (supplierError) { console.error('Supplier fetch error:', supplierError.message); }
    if (!supplier) return errorResponse(res, 404, 'Supplier not found');
    if (!supplier.email) return errorResponse(res, 400, `Supplier "${supplier.name}" has no email address on file.`);

    const { data: items } = await db.from('purchase_order_items').select('*').eq('purchase_order_id', purchaseOrderId);

    // Generate PDF
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.width;

    // Add logo top left
    try {
      doc.addImage(COMPANY_LOGO_B64, 'JPEG', 14, 10, 55, 18);
    } catch(e) {
      console.warn('Logo error:', e.message);
    }

    doc.setFontSize(22); doc.setFont('helvetica', 'bold');
    doc.text('PURCHASE ORDER', pageWidth - 14, 20, { align: 'right' });
    doc.setFontSize(12); doc.setFont('helvetica', 'normal');
    doc.text(po.po_number, pageWidth - 14, 27, { align: 'right' });

    let y = 40;
    doc.setFontSize(10);
    doc.text('VENDOR', 14, y); doc.text('SHIP TO', pageWidth / 2, y);
    doc.setLineWidth(0.2); doc.line(14, y + 2, pageWidth - 14, y + 2);
    y += 8;

    doc.setFontSize(11); doc.setFont('helvetica', 'bold');
    doc.text(supplier.name, 14, y); doc.text('FieldCalls Inc.', pageWidth / 2, y);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
    const supplierAddress = doc.splitTextToSize(supplier.address || '', (pageWidth / 2) - 20);
    doc.text(supplierAddress, 14, y + 5);
    doc.text('163 Zack Road', pageWidth / 2, y + 5);
    doc.text('Lutes Mountain, NB E1G 2V1', pageWidth / 2, y + 10);
    doc.text('Canada', pageWidth / 2, y + 15);
    y = Math.max(y + 20, y + 5 + supplierAddress.length * 4) + 10;

    doc.setFontSize(9); doc.setFont(undefined, 'bold');
    doc.text('Payment Terms:', 14, y); doc.text('Order Date:', 14, y + 5);
    doc.setFont(undefined, 'normal');
    doc.text(po.payment_type || 'N/A', 45, y);
    doc.text(po.order_date ? new Date(po.order_date).toLocaleDateString() : 'N/A', 45, y + 5);
    if (po.shipping_method) {
      doc.setFont(undefined, 'bold'); doc.text('Shipping:', 100, y);
      doc.setFont(undefined, 'normal'); doc.text(po.shipping_method, 125, y);
    }
    y += 15;

    y = drawTable(doc, items || [], y);

    if (y > doc.internal.pageSize.height - 60) { doc.addPage(); y = 20; } else { y += 10; }

    const totalsX = pageWidth - 70;
    const totalsXValue = pageWidth - 14;
    doc.setFontSize(10); doc.setFont('helvetica', 'normal');
    doc.text('Subtotal:', totalsX, y); doc.text(`$${(po.subtotal || 0).toFixed(2)}`, totalsXValue, y, { align: 'right' }); y += 7;
    doc.text('Tax:', totalsX, y); doc.text(`$${(po.tax_amount || 0).toFixed(2)}`, totalsXValue, y, { align: 'right' }); y += 7;
    doc.setFontSize(12); doc.setFont('helvetica', 'bold');
    doc.line(totalsX - 2, y, totalsXValue, y); y += 5;
    doc.text('Total:', totalsX, y);
    doc.text(`$${(po.total_amount || 0).toFixed(2)} ${po.currency || 'CAD'}`, totalsXValue, y, { align: 'right' });

    const pdfBase64 = doc.output('datauristring').split(',')[1];

    // Send email with PDF attachment
    const emailBody = message
      ? `<p>${message.replace(/\n/g, '<br>')}</p><hr style="margin:20px 0">`
      : '';

    await resend.emails.send({
      from: 'FieldCalls <noreply@tickets.fieldcalls.com>',
      replyTo: admin.email,
      to: supplier.email,
      subject: `Purchase Order ${po.po_number}`,
      html: `<!DOCTYPE html><html><body style="font-family:-apple-system,sans-serif;color:#111;max-width:600px;margin:0 auto;padding:20px">
        <div style="background:#111827;padding:20px 24px;border-radius:8px 8px 0 0">
          <p style="margin:0;color:#fff;font-size:18px;font-weight:700">FieldCalls Inc.</p>
          <p style="margin:4px 0 0;color:#9ca3af;font-size:13px">Purchase Order</p>
        </div>
        <div style="border:1px solid #e5e7eb;border-top:none;padding:24px;border-radius:0 0 8px 8px">
          <p>Dear ${supplier.name},</p>
          ${emailBody}
          <p>Please find attached Purchase Order <strong>${po.po_number}</strong> for your review.</p>
          <table style="width:100%;border-collapse:collapse;margin:16px 0;font-size:14px">
            <tr style="background:#f9fafb"><td style="padding:8px 12px;border:1px solid #e5e7eb"><strong>PO Number</strong></td><td style="padding:8px 12px;border:1px solid #e5e7eb">${po.po_number}</td></tr>
            <tr><td style="padding:8px 12px;border:1px solid #e5e7eb"><strong>Order Date</strong></td><td style="padding:8px 12px;border:1px solid #e5e7eb">${po.order_date ? new Date(po.order_date).toLocaleDateString() : 'N/A'}</td></tr>
            <tr style="background:#f9fafb"><td style="padding:8px 12px;border:1px solid #e5e7eb"><strong>Total Amount</strong></td><td style="padding:8px 12px;border:1px solid #e5e7eb"><strong>$${(po.total_amount || 0).toFixed(2)} ${po.currency || 'CAD'}</strong></td></tr>
            ${po.payment_type ? `<tr><td style="padding:8px 12px;border:1px solid #e5e7eb"><strong>Payment Terms</strong></td><td style="padding:8px 12px;border:1px solid #e5e7eb">${po.payment_type}</td></tr>` : ''}
          </table>
          <p style="color:#6b7280;font-size:13px">The PDF attachment contains the full details of this order. Please confirm receipt and expected delivery date.</p>
          <p>Thank you,<br><strong>${admin.full_name || 'FieldCalls Team'}</strong><br>FieldCalls Inc.</p>
        </div>
      </body></html>`,
      attachments: [
        {
          filename: `${po.po_number}.pdf`,
          content: pdfBase64,
          encoding: 'base64',
          content_type: 'application/pdf',
        }
      ],
    });

    // Update PO status to Sent if it was Draft
    if (po.status === 'Draft') {
      await db.from('purchase_orders').update({ status: 'Sent' }).eq('id', purchaseOrderId);
    }

    return res.json({ success: true, sentTo: supplier.email });
  } catch (err) {
    console.error('sendPurchaseOrder error:', err);
    if (err.status) return errorResponse(res, err.status, err.error);
    return errorResponse(res, 500, err.message || 'Failed to send purchase order');
  }
}
